"""Publish the historical comparison, data requirements and acceptance plan."""
import pathlib,json,html,shutil
root=pathlib.Path('.');j=json.loads((root/'dist/data/coimbra-validation.json').read_text(encoding='utf-8'));esc=html.escape
def num(x,n=2):return f'{x:,.{n}f}'.replace(',',' ').replace('.',',')
rows=''
for r in j['events']:
 if r['duration_assumed_h']!=24:continue
 m=r.get('comparison');rows+=f"<tr><td>{r['event']} · {r['date']}</td><td>{num(r['q_daily_m3s'])}</td><td>{num(r['overbank_area_m2']/10000)}</td><td>{num(m['simulated_area_m2']/10000) if m else '—'}</td><td>{num(m['iou_diagnostic']) if m else 'Sem mancha observada importada'}</td></tr>"
exposure=''
for p in j['parish_exposure']:
 if p['observed_flood_area_m2']<1:continue
 d=p['observed_census2021'];v=d['uniform_area_estimates'];u=d['intersected_units_upper_allocation_bounds'];props=p['properties']
 exposure+=f"<tr><td>{esc(props['freguesia'])}</td><td>{num(p['observed_flood_area_m2']/10000)}</td><td>{props.get('population_2021','—')}</td><td>{num(v[0]) if v else 'Desconhecido'}</td><td>{num(v[1]) if v else '—'} / {num(v[2]) if v else '—'}</td><td>0–{num(u[0],0) if u else '?'}</td></tr>"
requirements=[
 ('P0 · Geometria','Batimetria XYZ e secções atuais; cotas de margens, diques, pontes, açude e passagens','APA/ARH Centro, município, levantamentos UC/LNEC; origem histórica localizada não é levantamento atual','Cobertura contínua, data, precisão e datum documentados; substituir largura 150 m/incisão 2 m assumidas.'),
 ('P0 · Cotas compatíveis','Transformação do datum SNIRH/local para o terreno; marcas de cheia cotadas','APA/SNIRH, DGT e topografia de campo','Pontos de controlo e erro vertical medido; nunca somar zero de régua à cota já absoluta.'),
 ('P0 · Fronteiras no tempo','Q/H a 5–15 min, Ceira e Mondego, jusante do açude; descarga efetiva e posição de cada comporta','APA e operadores de Aguieira–Raiva/Fronhas/açude','Séries sincronizadas com fuso, qualidade, unidades e lacunas; não somar Aguieira a Raiva.'),
 ('P0 · Estruturas e memória','Hora/local/geometria das ruturas de 2001/2019, regras do açude e áreas de armazenamento','APA, Proteção Civil, município e relatórios de engenharia','Modelo não permanente 1D/2D com remanso, armazenamento, retorno e eventuais ruturas; conservar massa.'),
 ('P0 · Verdade independente','Manchas com hora, zonas observáveis/não observáveis, marcas e áreas confirmadas secas em 2001/2016/2019','EMSR417 obtido; arquivos municipais, UC, LNEC e Proteção Civil a obter','Separar eventos de ajuste e validação; comparar no instante da imagem, sem calibrar e avaliar com o mesmo dado.'),
 ('P1 · Exposição','CAOP integral, BGRI com cobertura verificada, edifícios residenciais, ocupação/pisos e equipamentos sensíveis','DGT, INE, município e entidades gestoras','Interseção na geometria integral, alocação por edifício, incerteza explícita; resolver compatibilidade CAOP2025/Censos2021.'),
 ('P1 · Vulnerabilidade e presença','Lares, escolas, dependência/mobilidade, população temporária agregada e hora de ocupação','Município/Proteção Civil, INE; operadores apenas mediante disponibilidade de dados agregados','Não reduzir vulnerabilidade a idade; dados autorizados e agregados. Nenhum feed de presença atual ligado.'),
 ('P1 · Decisão operacional','Tolerâncias para nível, tempo, omissões, falsas sinalizações e população; protocolo de falha de dados','Definir com utilizadores operacionais e revisão hidrológica independente','Aprovar critérios antes da validação reservada; não há limiar universal aplicado ou aceitação neste estudo.')]
table=''.join('<tr>'+''.join('<td>'+esc(c)+'</td>' for c in row)+'</tr>' for row in requirements)
body=f'''<h1>Coimbra: confronto hidráulico com cheias históricas</h1>
<p>24 de outubro de 2026 · avaliação reproduzível · referência independente de satélite</p>
<div class="notice"><strong>O piloto não passou a aceitação espacial.</strong><p>No confronto exploratório de 2019, a interseção na grelha é zero. A cobertura da imagem abrange a área do piloto, mas o caudal é diário, a imagem é posterior ao pico e o modelo não representa as ruturas e o armazenamento histórico. O resultado não valida alertas de freguesia nem contagens de pessoas atingidas.</p></div>
<h2>Referência observada e método</h2>
<p>Foi descarregado e verificado o produto <a href="https://mapping.emergency.copernicus.eu/activations/EMSR417/ALL/">Copernicus EMSR417, AOI01, delineação v1</a>. A imagem Sentinel‑1A é de <strong>23/12/2019 às 06:43 UTC</strong>, com resolução nominal 10 m. O produto refere erro geométrico RMSE até 12,5 m e limitações de deteção SAR em áreas urbanas e florestadas. Ausência de deteção não prova terreno seco.</p>
<p>O produto cobre cerca de {num(j['observed_all_aoi_m2']/10000)} ha inundados em toda a AOI. O recorte vetorial comum, retirando água permanente cartografada e o canal assumido de 150 m, deixa <strong>{num(j['observed_pilot_common_overbank_m2']/10000)} ha</strong> observados no piloto. A maior parte do Baixo Mondego fica fora deste piloto: estes resultados não avaliam toda a cheia de 2019.</p>
<p>Reexecutaram-se as mesmas equações do piloto sem ajustar parâmetros à imagem. Usou-se o caudal descarregado médio diário do açude (parâmetro SNIRH 2284, distinto da série de efluente total 212296818) como entrada uniforme ao longo dos 16 km, uma simplificação especialmente problemática nos ramos e a montante. As durações de 6 e 24 h são cenários de sensibilidade, não durações medidas. Em ambos a restrição de volume não alterou a mancha: o problema não se resolve apenas acrescentando volume de chuva. Não se reconstruíram hidrogramas instantâneos nem condições históricas de comportas.</p>
<h2>Resultados e discrepâncias</h2><div class="scroll"><table><tr><th>Evento / dia selecionado</th><th>Q médio diário m³/s</th><th>Área simulada total ha</th><th>Simulada no domínio comparável ha</th><th>IoU diagnóstico</th></tr>{rows}</table></div>
<p>Valores da duração assumida de 24 h; a de 6 h deu a mesma área. A coluna total precede as exclusões de água permanente e canal. No domínio comparável de 30 m existem 10,80 ha SAR e, no cenário do dia da imagem, 2,16 ha simulados, sem interseção. A diferença entre 10,62 ha vetoriais e 10,80 ha da grelha resulta da rasterização por centro de célula. A sensibilidade com tolerância espacial de 60 m também não recuperou interseção. Não se contabilizam as zonas não detetadas pelo SAR como falsos positivos confirmados.</p>
<img src="figures/13_validacao_2019.png" alt="Mancha observada e simulada: a interseção é nula nos dois cenários exploratórios"><p>© European Union, Copernicus EMS, EMSR417 AOI01 v1. Laranja: só observado; azul: só simulado; verde: interseção. A linha cinzenta indica a rede do piloto. Comparação no domínio comum após exclusões; não é mapa de segurança atual.</p>
<img src="figures/14_validacao_R.png" alt="Áreas simuladas por evento, gráfico produzido em R"><p>O máximo médio diário de 2019 foi em 21/12; a imagem é de 23/12. Uma comparação entre ambos só testa sensibilidade, não o desempenho no pico. Em 2001 e 2016 há reconstituições exploratórias, mas faltam manchas independentes importadas com hora: não se atribuem métricas espaciais a esses eventos.</p>
<h2>Freguesias e população: o que se pode concluir</h2>
<p>O recorte SAR sobre a CAOP2025 de apresentação intersecta as duas freguesias abaixo. São interseções parciais, não a freguesia inteira inundada. A população residente total é a correspondência Censos2021 disponível; a exposição é calculada pela fração de área BGRI2021 no recorte observado. São dados de épocas diferentes, não uma contagem de pessoas presentes ou atingidas em 2019.</p>
<div class="scroll"><table><tr><th>Freguesia</th><th>SAR ha</th><th>Residentes totais 2021</th><th>Exposição estimada por área</th><th>Crianças / 65+ estimados</th><th>Limites de alocação residentes</th></tr>{exposure}</table></div>
<p>Os limites 0–N significam apenas que a população de cada unidade BGRI pode estar concentrada dentro ou fora da interseção. Não são intervalos de confiança e não devem ser somados entre freguesias, pois uma unidade pode atravessar limites administrativos. Crianças e idosos são indicadores parciais de vulnerabilidade; faltam dependência, edifícios ocupados, pisos, equipamentos e população temporária. Os valores fracionários revelam a hipótese de distribuição uniforme e não devem aparecer como pessoas confirmadas.</p>
<h2>Dados em falta e critérios de confiança</h2><div class="scroll"><table><tr><th>Prioridade</th><th>Dado necessário</th><th>Origem a consultar</th><th>Condição de utilização</th></tr>{table}</table></div>
<h2>Sequência para uma validação aceite</h2><ol><li>Congelar dados e geometria por evento, resolver referências verticais e instalar condições de fronteira e estruturas num modelo não permanente.</li><li>Ajustar apenas em eventos de treino e fixar os parâmetros antes do confronto independente. A imagem de 2019 já foi usada para diagnóstico: futuras correções exigem outro evento ou referência reservada para aceitação.</li><li>Calcular erro de nível e hora do pico, balanço de massa, IoU/recall em zonas observáveis, omissões em localidades e falsas sinalizações em controlos secos confirmados; testar resolução, rugosidade e incerteza das entradas.</li><li>Propagar as incertezas a edifícios, freguesias e exposição; definir limiares com revisão independente e utilizadores operacionais. Só depois ativar sinalização de água efetivamente prevista numa freguesia.</li></ol>
<h2>Dados, R e reprodução</h2><p><a href="data/coimbra-validation.json">Resultados e proveniência JSON</a> · <a href="analysis/coimbra-historical-comparison.csv">Comparações CSV</a> · <a href="analysis/coimbra-validation.R">Código R</a> · <a href="data/coimbra-observed-2019.geojson">Recorte SAR GeoJSON</a> · <a href="data/coimbra-hindcast-2019.geojson">Simulação exploratória GeoJSON</a></p>
<p>Fonte original: <a href="{j['source_url']}">pacote vetorial oficial</a>. SHA256 <code>{j['source_zip_sha256']}</code>. Cálculo: tools/fetch-validation.cjs, extração segura do ZIP para research/emsr417, tools/validate-coimbra.py, tools/coimbra-validation.R e tools/validation-document.py. O confronto não é refeito a cada atualização de telemetria; é um estudo histórico congelado. A CI verifica métricas e impede aceitação automática.</p>
<p>Outras referências: <a href="https://www.cm-coimbra.pt/wp-content/uploads/2022/03/Programa-Municipal-para-as-Alteracoes-Climaticas-vf.pdf">Programa Municipal para as Alterações Climáticas</a> (episódios e impactos), <a href="https://snirh.apambiente.pt/snirh/download/relatorios/cheias_mondego_2001.pdf">SNIRH, cheias de 2001</a> e <a href="https://www.riscos.pt/wp-content/uploads/2018/SEC/10/eBook_SEC_10_03.pdf">estudo das cheias de janeiro de 2016</a>. Fotografias e relatos não foram transformados em polígonos ou cotas exatas.</p>'''
css='body{max-width:1120px;margin:35px auto;padding:0 22px;font:16px/1.65 system-ui;color:#173c47;background:#f7faf9}h1{line-height:1.2}h2{margin-top:36px}img{width:100%}a{color:#007c87}table{border-collapse:collapse;width:100%;font-size:14px}td,th{text-align:left;border-bottom:1px solid #ccd8d8;padding:9px;vertical-align:top}.scroll{overflow-x:auto}.notice{background:#fff0d8;border-left:4px solid #d8a040;padding:20px}code{overflow-wrap:anywhere}nav{display:flex;gap:20px;flex-wrap:wrap}'
page='<!doctype html><html lang="pt-PT"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Coimbra · validação histórica</title><style>'+css+'</style><nav><a href="./">Mapa</a><a href="operational-review.html">Avaliação operacional</a><a href="article.html">Artigo</a></nav>'+body+'</html>'
(root/'dist/validation.html').write_text(page,encoding='utf-8')
(root/'docs/VALIDACAO_HISTORICA_COIMBRA.md').write_text('# Validação histórica de Coimbra\n\nRelatório completo: https://dsantananet.github.io/ignispyro-floods/validation.html\n\n'+body,encoding='utf-8')
shutil.copyfile(root/'tools/coimbra-validation.R',root/'dist/analysis/coimbra-validation.R')
